ками та ланцюгами. Сніг і лід змінюють складність; перевірте повідомлення TPN: https://tpn.gov.pl/komunikat-turystyczny"}, "zh": {"name": "Rysy：从Palenica Białczańska沿红色步道上山", "description": "经Morskie Oko及Czarny Staw pod Rysami登波兰侧峰顶。这是单程上山路线，下山需另行规划。", "notes": "已反转PTTK轨迹：原资料反向耗时6小时45分，原下降1837米对应本方向爬升。此为有陡坡、暴露路段及铁链的高山路线。积雪和结冰会改变难度；出发前请查看TPN公告：https://tpn.gov.pl/komunikat-turystyczny"}}, "distance_source_url": "https://malopolska.szlaki.pttk.pl/461-pttk-malopolska-rysy-polana-palenica", "distance_verified_at": "2026-11-17T00:00:00Z", "elevation_gain_source_url": "https://malopolska.szlaki.pttk.pl/461-pttk-malopolska-rysy-polana-palenica", "elevation_gain_verified_at": "2026-11-17T00:00:00Z", "time_source_url": "https://malopolska.szlaki.pttk.pl/461-pttk-malopolska-rysy-polana-palenica", "time_verified_at": "2026-11-17T00:00:00Z"}}, {"kind": "poi", "body": {"peak_slug": "rysy", "type_slug": "shelter", "latitude": 49.201319, "longitude": 20.070794, "trail_id": null, "active": true, "source_url": "https://malopolska.szlaki.pttk.pl/2725-pttk-malopolska-schronisko-gorskie-pttk-nad-morskim-okiem", "last_verified_at": "2026-11-17T00:00:00Z", "website_url": "https://malopolska.szlaki.pttk.pl/2725-pttk-malopolska-schronisko-gorskie-pttk-nad-morskim-okiem", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=49.201319,20.070794", "i18n": {"pl": {"name": "Schronisko PTTK nad Morskim Okiem", "description": "Schronisko nad jeziorem Morskie Oko, przy czerwonym szlaku prowadzącym w stronę Rysów.", "tips": "Sprawdź bieżące zasady dostępu u zarządcy; nie potwierdzono godzin, cen ani dostępności usług."}, "en": {"name": "PTTK mountain hut at Morskie Oko", "description": "Mountain hut by Morskie Oko lake on the red trail towards Rysy.", "tips": "Check current access rules with the operator; opening hours, prices and service availability are not confirmed."}, "ua": {"name": "Притулок PTTK над Morskie Oko", "description": "Притулок біля озера Morskie Oko на червоному маршруті в напрямку Рисів.", "tips": "Перевірте актуальні правила доступу в адміністрації; години роботи, ціни й доступність послуг не підтверджено."}, "zh": {"name": "Morskie Oko湖畔PTTK山屋", "description": "位于Morskie Oko湖畔、通往Rysy的红色步道旁的山屋。", "tips": "请向管理方核实当前通行规定；未确认开放时间、费用或服务可用性。"}}}}, {"kind": "trail", "body": {"peak_slug": "lackowa", "slug": "lackowa-izby-zolty-wejscie", "start_point_name": "Izby", "end_point_name": "Lackowa", "distance_km": 4.8, "elevation_gain_m": 410, "time_min": 115, "difficulty": null, "route_type": "point-to-point", "active": true, "source_url": "https://malopolska.szlaki.pttk.pl/3865-pttk-malopolska-lackowa-izby", "last_verified_at": "2026-11-17T00:00:00Z", "map_url": "https://malopolska.szlaki.pttk.pl/3865-pttk-malopolska-lackowa-izby", "gpx_url": "https://raw.githubusercontent.com/Silentmaster86/peakguide/main/docs/catalogue/batch-04/routes/lackowa-izby-zolty-wejscie.gpx", "route_geometry": {"type": "MultiLineString", "coordinates": [[[21.06597856, 49.43992669], [21.06632883, 49.43968234], [21.06649781, 49.43946802], [21.066765, 49.438995], [21.067228, 49.438744], [21.067622, 49.438428], [21.06906257, 49.43714589]], [[21.06906257, 49.43714589], [21.07056499, 49.43584528], [21.0718739, 49.43391416], [21.07271075, 49.43288109], [21.07326865, 49.43149898], [21.07371926, 49.42935594], [21.0741806, 49.42740362], [21.07442737, 49.42586777], [21.07473911, 49.42544745]], [[21.07473911, 49.42544745], [21.07574701, 49.42561049], [21.07705593, 49.42530341], [21.07905149, 49.42555465], [21.08132601, 49.42506613], [21.0820663, 49.42517779], [21.08331084, 49.42607807], [21.08581066, 49.4266922], [21.08661801, 49.42713357], [21.08761579, 49.42751739], [21.08993322, 49.42794308], [21.09018397, 49.42806894]], [[21.09018397, 49.42806894], [21.08991444, 49.42861558], [21.08982861, 49.42933809], [21.08989835, 49.42964176], [21.08985543, 49.429914], [21.08958721, 49.43056669], [21.08994126, 49.430996], [21.09027386, 49.43129858], [21.09214067, 49.43210133], [21.09281123, 49.43220603], [21.0935837, 49.4325376], [21.09438837, 49.43280634], [21.09519303, 49.43289359], [21.09549344, 49.43284124], [21.09587967, 49.43269466], [21.0960567, 49.43247478], [21.09618545, 49.4321816], [21.09666824, 49.43189192], [21.09692574, 49.43166505], [21.0978806, 49.43144284], [21.09908938, 49.43111127], [21.09999061, 49.43050047], [21.10106528, 49.42970351], [21.10136032, 49.42934401], [21.10184312, 49.42895308], [21.10199332, 49.42868083], [21.10193431, 49.42827943], [21.10163569, 49.42789432], [21.101046293333, 49.427302753333]], [[21.101046293333, 49.427302753333], [21.10173225, 49.42687202], [21.102469, 49.426524]]]}, "geometry_source_url": "https://malopolska.szlaki.pttk.pl/item/gpx/3865", "geometry_verified_at": "2026-11-17T00:00:00Z", "i18n": {"pl": {"name": "Lackowa: żółtym szlakiem z Izb", "description": "Podejście z Izb żółtym szlakiem na Lackową, z końcowym odcinkiem przy szlaku granicznym. GPX obejmuje tylko wejście, bez powrotu.", "notes": "Odwrócono pełny GPX PTTK Lackowa–Izby. Czas wejścia 1:55 h podano dla kierunku przeciwnego; 410 m podejść to suma zejść w źródle. To wariant żółty, nie strome czerwone podejście zachodnim stokiem. Sprawdź aktualne oznakowanie i warunki."}, "en": {"name": "Lackowa: yellow-trail ascent from Izby", "description": "Ascent from Izby along the yellow trail to Lackowa, finishing near the border trail. GPX covers the ascent only, without the return.", "notes": "Full PTTK Lackowa–Izby GPX reversed. The source gives 1:55 h for ascent in reverse and 410 m descent in the original direction. This is the yellow route, not the steep red western ascent. Check current signs and conditions."}, "ua": {"name": "Лацкова: підйом жовтим маршрутом з Izby", "description": "Підйом з Izby жовтим маршрутом на Лацкову, з кінцевою ділянкою біля прикордонної стежки. GPX містить лише підйом, без повернення.", "notes": "Повний GPX PTTK Lackowa–Izby розвернуто. Джерело дає 1:55 год для зворотного напрямку; 410 м спуску стають підйомом. Це жовтий варіант, а не крутий червоний підйом західним схилом. Перевірте актуальні знаки та умови."}, "zh": {"name": "Lackowa：从Izby沿黄色步道上山", "description": "从Izby沿黄色步道登Lackowa，末段位于边境步道附近。GPX仅含上山，不含返程。", "notes": "已反转完整PTTK Lackowa–Izby轨迹。原资料反向耗时1小时55分，原下降410米对应本方向爬升。这是黄色路线，并非西坡陡峭的红色登山路线。请核实当前标识和路况。"}}, "distance_source_url": "https://malopolska.szlaki.pttk.pl/3865-pttk-malopolska-lackowa-izby", "distance_verified_at": "2026-11-17T00:00:00Z", "elevation_gain_source_url": "https://malopolska.szlaki.pttk.pl/3865-pttk-malopolska-lackowa-izby", "elevation_gain_verified_at": "2026-11-17T00:00:00Z", "time_source_url": "https://malopolska.szlaki.pttk.pl/3865-pttk-malopolska-lackowa-izby", "time_verified_at": "2026-11-17T00:00:00Z"}}, {"kind": "poi", "body": {"peak_slug": "lackowa", "type_slug": "attraction", "latitude": 49.426363, "longitude": 21.102584, "trail_id": null, "active": true, "source_url": "https://malopolska.szlaki.pttk.pl/2254-pttk-malopolska-lackowa", "last_verified_at": "2026-11-17T00:00:00Z", "website_url": "https://malopolska.szlaki.pttk.pl/2254-pttk-malopolska-lackowa", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=49.426363,21.102584", "i18n": {"pl": {"name": "Lackowa — zalesiony wierzchołek przy granicy", "description": "Punkt orientacyjny na zalesionym szczycie w grzbiecie granicznym polskiej części Beskidu Niskiego.", "tips": "Sprawdź bieżące zasady dostępu u zarządcy; nie potwierdzono godzin, cen ani dostępności usług."}, "en": {"name": "Lackowa — wooded border summit", "description": "A landmark on the wooded summit along the border ridge in the Polish Low Beskids.", "tips": "Check current access rules with the operator; opening hours, prices and service availability are not confirmed."}, "ua": {"name": "Лацкова — лісиста прикордонна вершина", "description": "Орієнтир на лісистій вершині прикордонного хребта польської частини Низьких Бескидів.", "tips": "Перевірте актуальні правила доступу в адміністрації; години роботи, ціни й доступність послуг не підтверджено."}, "zh": {"name": "Lackowa：边境林间山顶", "description": "波兰低贝斯基德地区边境山脊上的林间峰顶地标。", "tips": "请向管理方核实当前通行规定；未确认开放时间、费用或服务可用性。"}}}}, {"kind": "trail", "body": {"peak_slug": "wysoka-kopa", "slug": "wysoka-kopa-sine-skalki-czerwony-odcinek", "start_point_name": "Rozdroże pod Izerskimi Garbami", "end_point_name": "Sine Skałki", "distance_km": null, "elevation_gain_m": null, "time_min": null, "difficulty": null, "route_type": "point-to-point", "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/693-dolnoslaskie-glowny-szlak-sudecki-im-mieczyslawa-orlowicza", "last_verified_at": "2026-11-17T00:00:00Z", "map_url": "https://dolnoslaskie.szlaki.pttk.pl/693-dolnoslaskie-glowny-szlak-sudecki-im-mieczyslawa-orlowicza", "gpx_url": "https://raw.githubusercontent.com/Silentmaster86/peakguide/main/docs/catalogue/batch-04/routes/wysoka-kopa-sine-skalki-czerwony-odcinek.gpx", "route_geometry": {"type": "MultiLineString", "coordinates": [[[15.43484001, 50.84650696], [15.43475803, 50.84665096], [15.43461403, 50.847131], [15.43449098, 50.84723904], [15.43446097, 50.84733903], [15.43456198, 50.84747097], [15.43436299, 50.84766299], [15.43425797, 50.84785804], [15.43425, 50.84796298], [15.43417599, 50.84807203], [15.43404498, 50.84822802], [15.43386402, 50.84836498], [15.43349697, 50.84852197], [15.43342103, 50.84867301], [15.43320696, 50.84872699], [15.43296103, 50.84887502], [15.43287001, 50.849002], [15.43270899, 50.84909102], [15.432552, 50.84911902], [15.43248603, 50.849318], [15.43221597, 50.849691], [15.43205604, 50.84982703], [15.43186904, 50.849907], [15.43181104, 50.849993], [15.431863, 50.85008402], [15.43175898, 50.85022501], [15.43162303, 50.85027102], [15.43128298, 50.85053497], [15.43064998, 50.85082197], [15.43041, 50.850857], [15.429533, 50.85110896], [15.42925397, 50.85115003], [15.42891702, 50.85116898], [15.42852645, 50.85138724], [15.42898355, 50.85175482], [15.42701198, 50.852022], [15.42623598, 50.85226801], [15.425178, 50.85245604], [15.42442901, 50.85248996], [15.42423962, 50.85289187], [15.42417265, 50.85298592], [15.42385263, 50.85329387], [15.4230856, 50.85386887], [15.42288963, 50.85400189], [15.42240155, 50.8542385], [15.42122997, 50.85458502], [15.42085304, 50.85484997], [15.42065497, 50.85523797], [15.42055463, 50.85536062], [15.41936601, 50.85597801], [15.41895504, 50.85633198], [15.41826999, 50.85675904], [15.41810696, 50.856896], [15.41781039, 50.85722635], [15.417495, 50.85774802], [15.417021, 50.85835503], [15.41668849, 50.85919903], [15.41644399, 50.85934703], [15.41507612, 50.85977766], [15.41492214, 50.85978973], [15.41417313, 50.85968672], [15.41327317, 50.85945672], [15.41217564, 50.85896022], [15.41159089, 50.85877216], [15.40983186, 50.85798518], [15.4093489, 50.85779416], [15.40844089, 50.85753717], [15.40786186, 50.85725613], [15.4075992, 50.85720138], [15.40650699, 50.85726002], [15.40567101, 50.85747409]]]}, "geometry_source_url": "https://dolnoslaskie.szlaki.pttk.pl/item/gpx/693", "geometry_verified_at": "2026-11-17T00:00:00Z", "i18n": {"pl": {"name": "Wysoka Kopa: czerwony szlak do Sinych Skałek — bez wejścia na szczyt", "description": "Wybrany odcinek Głównego Szlaku Sudeckiego od Rozdroża pod Izerskimi Garbami do Sinych Skałek, w masywie Wysokiej Kopy. Nie prowadzi na zamknięty wierzchołek Wysokiej Kopy.", "notes": "PTTK podaje zamknięcie dojścia na szczyt dla ochrony cietrzewia. Pozostań na znakowanym szlaku; GPX nie zawiera odejścia na wierzchołek. Nie przypisano parametrów pełnej trasy 78,7 km do krótkiego odcinka. Sprawdź komunikaty nadleśnictwa: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}, "en": {"name": "Wysoka Kopa: red trail to Sine Skałki — no summit access", "description": "Selected Main Sudetes Trail section from Rozdroże pod Izerskimi Garbami to Sine Skałki in the Wysoka Kopa massif. It does not reach the closed Wysoka Kopa summit.", "notes": "PTTK reports summit access closed to protect black grouse. Stay on the marked trail; GPX includes no summit spur. Metrics of the full 78.7 km route were not assigned to this short section. Check forestry announcements: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}, "ua": {"name": "Висока Копа: червоний маршрут до Sine Skałki — без виходу на вершину", "description": "Вибрана ділянка Головного Судетського шляху від Rozdroże pod Izerskimi Garbami до Sine Skałki в масиві Високої Копи. На закриту вершину Високої Копи маршрут не веде.", "notes": "PTTK повідомляє про закриття підходу на вершину для охорони тетерука. Залишайтеся на маркованій стежці; GPX не містить відгалуження на вершину. Показники повного маршруту 78,7 км не перенесено на коротку ділянку. Перевірте повідомлення лісництва: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}, "zh": {"name": "Wysoka Kopa：沿红色步道到Sine Skałki，不登峰顶", "description": "截取苏台德主步道从Rozdroże pod Izerskimi Garbami至Wysoka Kopa山体内Sine Skałki的一段，不通往已关闭的Wysoka Kopa峰顶。", "notes": "PTTK资料说明，为保护黑琴鸡，峰顶接近路段已关闭。请留在标记步道上；GPX不含登顶支线。未将完整78.7公里路线的数据套用于此短段。请核实林区公告：https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}}, "distance_source_url": null, "distance_verified_at": null, "elevation_gain_source_url": null, "elevation_gain_verified_at": null, "time_source_url": null, "time_verified_at": null}}, {"kind": "poi", "body": {"peak_slug": "wysoka-kopa", "type_slug": "viewpoint", "latitude": 50.857504, "longitude": 15.405716, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/2035-dolnoslaskie-wysoka-kopa-sine-skalki", "last_verified_at": "2026-11-17T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/2035-dolnoslaskie-wysoka-kopa-sine-skalki", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.857504,15.405716", "i18n": {"pl": {"name": "Sine Skałki — punkt przy czerwonym szlaku", "description": "Punkt widokowy i miejsce odpoczynku w masywie Wysokiej Kopy. To osobny punkt przy szlaku, nie zamknięty wierzchołek Wysokiej Kopy.", "tips": "Sprawdź bieżące zasady dostępu u zarządcy; nie potwierdzono godzin, cen ani dostępności usług."}, "en": {"name": "Sine Skałki — landmark on the red trail", "description": "A viewpoint and rest location in the Wysoka Kopa massif. This is a separate trail landmark, not the closed Wysoka Kopa summit.", "tips": "Check current access rules with the operator; opening hours, prices and service availability are not confirmed."}, "ua": {"name": "Sine Skałki — орієнтир на червоному маршруті", "description": "Оглядова точка та місце відпочинку в масиві Високої Копи. Це окремий орієнтир біля стежки, а не закрита вершина Високої Копи.", "tips": "Перевірте актуальні правила доступу в адміністрації; години роботи, ціни й доступність послуг не підтверджено."}, "zh": {"name": "Sine Skałki：红色步道旁地标", "description": "Wysoka Kopa山体内的观景及休息地点。这是步道旁的独立地标，并非已关闭的Wysoka Kopa峰顶。", "tips": "请向管理方核实当前通行规定；未确认开放时间、费用或服务可用性。"}}}}]$records$::jsonb) loop
 body=entry->'body';
 select id into peak from public.peaks where slug=body->>'peak_slug' and id=(case body->>'peak_slug' when 'rysy' then 16 when 'lackowa' then 23 when 'wysoka-kopa' then 3 end) and active=true for update;
 if peak is null then raise exception 'Peak missing or changed: %',body->>'peak_slug'; end if;
 body=body||jsonb_build_object('peak_id',peak);
 if entry->>'kind'='trail' then
  if exists(select from public.trails where slug=body->>'slug') then raise exception 'Trail slug already exists: %',body->>'slug'; end if;
  trail=jsonb_populate_record(null::public.trails,body);
 insert into public.trails (peak_id, slug, start_point_name, end_point_name, distance_km, elevation_gain_m, time_min, difficulty, route_type, active, source_url, last_verified_at, map_url, gpx_url, distance_source_url, distance_verified_at, elevation_gain_source_url, elevation_gain_verified_at, time_source_url, time_verified_at, route_geometry, geometry_source_url, geometry_verified_at) values (trail.peak_id, trail.slug, trail.start_point_name, trail.end_point_name, trail.distance_km, trail.elevation_gain_m, trail.time_min, trail.difficulty, trail.route_type, trail.active, trail.source_url, trail.last_verified_at, trail.map_url, trail.gpx_url, trail.distance_source_url, trail.distance_verified_at, trail.elevation_gain_source_url, trail.elevation_gain_verified_at, trail.time_source_url, trail.time_verified_at, trail.route_geometry, trail.geometry_source_url, trail.geometry_verified_at) returning id into saved_id;
 for lang,tr in select key,value from jsonb_each(body->'i18n') loop
 insert into public.trails_i18n (trail_id,lang,name, description, notes) values (saved_id,lang,tr->>'name', tr->>'description', tr->>'notes'); end loop;
 select jsonb_build_object('row',to_jsonb(r),'i18n',(select jsonb_agg(to_jsonb(i) order by i.lang) from public.trails_i18n i where trail_id=r.id)) into actual from public.trails r where id=saved_id;
 snapshot=snapshot||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','id',saved_id,'snapshot',actual));
 else
  if exists(select from public.pois where peak_id=peak and source_url=body->>'source_url') then raise exception 'POI source already exists'; end if;
  select id into saved_id from public.poi_types where slug=body->>'type_slug';
  if saved_id is null then raise exception 'Missing POI type'; end if;
  body=body||jsonb_build_object('type_id',saved_id);
  poi=jsonb_populate_record(null::public.pois,body);
 insert into public.pois (peak_id, trail_id, type_id, latitude, longitude, active, source_url, last_verified_at, website_url, google_maps_url) values (poi.peak_id, poi.trail_id, poi.type_id, poi.latitude, poi.longitude, poi.active, poi.source_url, poi.last_verified_at, poi.website_url, poi.google_maps_url) returning id into saved_id;
 for lang,tr in select key,value from jsonb_each(body->'i18n') loop
 insert into public.pois_i18n (poi_id,lang,name, description, tips) values (saved_id,lang,tr->>'name', tr->>'description', tr->>'tips'); end loop;
 select jsonb_build_object('row',to_jsonb(r),'i18n',(select jsonb_agg(to_jsonb(i) order by i.lang) from public.pois_i18n i where poi_id=r.id)) into actual from public.pois r where id=saved_id;
 snapshot=snapshot||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','id',saved_id,'snapshot',actual));
 end if;
 end loop;
 insert into peakguide_private.catalogue_batch_receipts(batch_key,snapshot)values('kgp-04',snapshot);
 raise notice 'Added 3 trails and 3 POIs, each in four languages';
end $batch$;
commit;
